const{invoke:invoke}=window.__TAURI__.core,preview=document.getElementById("preview"),loadBtn=document.getElementById("load-btn"),contrastSlider=document.getElementById("contrast"),contrastValue=document.getElementById("contrast-value"),maxWidthInput=document.getElementById("max-width"),maxHeightInput=document.getElementById("max-height"),dimensionsInfo=document.getElementById("dimensions-info");let hasImage=!1;async function applyAdjustments(){if(hasImage)try{const t=await invoke("apply_image_adjustments",{params:{contrast:parseFloat(contrastSlider.value),max_width:parseInt(maxWidthInput.value,10),max_height:parseInt(maxHeightInput.value,10)}});preview.src=`data:image/png;base64,${t.base64_png}`,dimensionsInfo.textContent=`Dimensions traitées : ${t.width} x ${t.height}`}catch(t){alert(`Erreur: ${t}`)}}loadBtn.addEventListener("click",(async()=>{try{const t=await invoke("load_image");preview.src=`data:image/png;base64,${t.base64_png}`,dimensionsInfo.textContent=`Dimensions originales : ${t.width} x ${t.height}`,hasImage=!0}catch(t){alert(`Erreur: ${t}`)}})),contrastSlider.addEventListener("input",(()=>{contrastValue.textContent=contrastSlider.value})),contrastSlider.addEventListener("change",applyAdjustments),maxWidthInput.addEventListener("change",applyAdjustments),maxHeightInput.addEventListener("change",applyAdjustments);